/** Build a consistent disclosure and source block without claiming that prices are current forever. */
function livingtmw_experience_post_footer( string $checked, array $sources = array() ): string {
	$html  = '<div class="livingtmw-field-note"><strong>경험 범위</strong> 이 글의 가격과 조건은 작성자가 양곤에서 직접 이용하며 확인한 사례입니다. 지점, 재고, 계약, 환율과 시기에 따라 달라질 수 있으므로 결제·계약 전 판매처에 다시 확인하세요.</div>';
	if ( empty( $sources ) ) {
		return $html;
	}
	$html .= '<div class="livingtmw-field-sources"><h2>확인 자료</h2><ul>';
	foreach ( $sources as $label => $url ) {
		$html .= '<li><a href="' . esc_url( $url ) . '" target="_blank" rel="noopener noreferrer">' . esc_html( $label ) . '</a> <span>(확인: ' . esc_html( $checked ) . ')</span></li>';
	}
	return $html . '</ul></div>';
}

/** Return the complete editorial calendar. */
function livingtmw_august_experience_posts(): array {
	$marketplace_photo = livingtmw_field_photo( 'myanmar-plaza-kids-ride-redacted.png', 'Myanmar Plaza 5층 어린이 놀이시설을 이용하는 모습' );
	$purifier_photo   = livingtmw_field_photo( '정수기.jpg', '양곤 가정에서 실제 사용 중인 Coway 냉온정수기' );
	$coco_photo       = livingtmw_field_photo( 'time-city-coco-redacted.png', 'Time City Coco 실내 놀이공간의 주말 캐릭터 행사' );
	$checked          = '2026-08-22';

	return array(
		array(
			'date'    => '2026-08-22 09:00:00',
			'slug'    => 'myanmar-plaza-market-place-family-shopping',
			'title'   => '아이와 Myanmar Plaza 가는 날: Market Place 장보기 실제 비용과 동선',
			'excerpt' => 'Myanmar Plaza와 Golden Valley Market Place를 직접 이용하며 알게 된 신선식품 선택법, KBZPay 결제, 시장 배달과의 가격 차이, 아이와 함께 움직이는 동선을 정리했습니다.',
			'content' => '<p class="livingtmw-field-badge">2026년 8월 · 양곤 거주 가족의 직접 이용 기록</p><p>우리 가족이 Myanmar Plaza를 자주 찾는 이유는 장보기 하나만이 아닙니다. 몰 안의 Market Place에서 필요한 식재료를 사고, 5층에서 아이가 좋아하는 놀이기구와 말 디자인 전동열차를 타면 한 번의 외출로 장보기와 아이의 놀이를 함께 해결할 수 있습니다. 반면 신선한 고기와 채소가 우선인 날에는 Golden Valley Market Place와 현지 시장 배달을 나누어 이용합니다. 두 지점 모두 같은 이름의 마트지만 실제로 써 보니 잘 맞는 용도가 달랐습니다.</p>' . $marketplace_photo . '<h2>Myanmar Plaza점은 가족 외출과 묶을 때 편했습니다</h2><p>Myanmar Plaza 안의 Market Place는 몰 지점이라 Golden Valley점보다 제품군이 아주 다양하다는 느낌은 받지 못했습니다. 그래도 우리 집이 평소 사는 기본 식품과 생활용품은 대부분 갖추고 있어 크게 불편하지 않았습니다. 여러 매장을 돌아다닐 필요 없이 식사나 아이 일정과 함께 장을 볼 수 있다는 것이 장점입니다.</p><p>5층의 어린이 놀이시설도 방문 빈도를 높인 이유입니다. 우리 아이는 말 디자인 전동열차를 특히 좋아합니다. 이용료는 2026년 8월 경험 기준 6,000짯이었고 이 시설은 현금으로 결제했습니다. 좌석은 운전석을 포함해 6줄이고 한 줄에 두 명이 앉을 수 있었습니다. 아이가 어리면 보호자가 함께 탈 수 있어 첫 이용의 부담이 적었습니다. 사진에 보이는 것은 전동열차 자체가 아니라 같은 층에 있는 별도의 놀이기구입니다.</p><h2>신선식품은 Golden Valley점을 더 자주 선택합니다</h2><p>집에서 요리할 고기, 생선, 채소와 과일이 필요할 때는 Golden Valley Market Place를 선호합니다. 직접 봤을 때 채소와 과일, 육류의 상태가 비교적 신선했고 조리 결과도 안정적이었습니다. 닭고기는 지금까지 실패가 없었고 돼지고기는 한 번 냄새가 강해 사용하기 어려웠던 경험이 있습니다. 그 뒤로 돼지고기는 색을 먼저 보고, 가능하면 포장 상태와 냄새도 확인합니다. 날짜만 보고 고르기보다 실제 상태를 함께 확인하는 편이 낫다는 교훈을 얻었습니다.</p><div class="livingtmw-table-wrap"><table><thead><tr><th>구매처</th><th>우리 집이 주로 사는 것</th><th>선택 이유</th></tr></thead><tbody><tr><td>Myanmar Plaza Market Place</td><td>기본 식품·생활용품</td><td>아이와 외출 동선에 넣기 편함</td></tr><tr><td>Golden Valley Market Place</td><td>돼지고기·닭고기·생선·과일</td><td>직접 상태를 비교하기 좋았음</td></tr><tr><td>현지 시장 Viber 배달</td><td>대파·무·양파·제철과일</td><td>크기와 신선도가 더 좋았던 품목이 많음</td></tr></tbody></table></div><h2>가격은 편의성과 함께 비교해야 합니다</h2><p>Market Place의 가장 큰 단점은 시장보다 확실히 비싸게 느껴진다는 점입니다. 2026년 8월에 확인한 대파 한 대는 10,000짯, 불닭볶음면 컵라면 한 개는 22,000짯이었습니다. 당시 우리 집 체감 환산으로 각각 약 3,000원, 수입 컵라면은 그보다 훨씬 부담스러운 가격이었습니다. 환율이 자주 달라지므로 원화 환산액보다 매장에서 본 짯 가격과 확인 날짜를 기록하는 편이 정확합니다.</p><p>우리 가족은 한 번 장을 보면 대개 20만~30만 짯을 씁니다. 현금으로 내면 최고액권인 1만 짯 지폐를 여러 장 준비해야 하고 잔돈도 많이 생겨 대부분 KBZPay로 결제합니다. 다만 5층 놀이시설처럼 현금만 받는 곳이 있어 소액 현금은 따로 챙깁니다.</p><h2>우리 가족의 실패를 줄인 장보기 순서</h2><ol><li>아이 일정이 있는 날은 Myanmar Plaza에서 기본 품목만 빠르게 삽니다.</li><li>고기와 생선은 Golden Valley점에서 색, 냄새와 포장 상태를 직접 봅니다.</li><li>대파, 무, 양파와 제철과일은 시장 담당자에게 Viber로 주문합니다.</li><li>냉장 식품은 외출 마지막에 사고 집에 바로 돌아옵니다.</li><li>KBZPay 잔액과 놀이시설용 현금을 나누어 준비합니다.</li></ol><h2>자주 묻는 질문</h2><h3>두 Market Place 중 한 곳만 고른다면?</h3><p>아이와 몰에서 시간을 보낼 계획이면 Myanmar Plaza점, 신선식품을 자세히 고를 목적이면 우리 가족에게는 Golden Valley점이 더 잘 맞았습니다.</p><h3>고기는 항상 신선했나요?</h3><p>아닙니다. 닭고기는 실패가 없었지만 돼지고기는 한 번 냄새 때문에 실패했습니다. 이 글은 품질 보증이 아니라 매번 상태를 확인해야 한다는 경험담입니다.</p>' . livingtmw_experience_post_footer( $checked, array( 'Marketplace Golden Valley 공식 시설 안내' => 'https://www.citypropertiesmm.com/shopping-centers/marketplace-golden-valley/', 'Myanmar Plaza 공식 디렉터리의 Marketplace 안내' => 'https://haglmm.com/mmplaza/directory/' ) ),
		),
		array(
			'date'    => '2026-08-23 09:00:00',
			'slug'    => 'yangon-viber-vegetable-delivery-maso',
			'title'   => '양곤에서 Viber로 채소 주문하기: 마쏘 당일 배달 이용 경험',
			'excerpt' => '영어 이름이나 사진으로 주문하고 영수증을 확인하는 양곤 시장 배달 과정, 약 3만 짯 주문 사례와 우기철 교환 경험을 정리했습니다.',
			'content' => '<p class="livingtmw-field-badge">2026년 8월 · 마쏘 채소 배달 직접 주문 기록</p><p>양곤에서 채소를 살 때 꼭 시장에 직접 갈 필요는 없었습니다. 우리 집은 ‘마쏘’라는 야채가게 담당자에게 Viber 메시지를 보내 대파, 무, 양파, 용과, 망고와 제철과일을 주문합니다. 마트보다 무조건 싸다고 단정할 수는 없지만 크기와 신선도에서 만족한 경우가 많았고 배달비가 따로 들지 않아 일상적인 장보기 방법으로 자리 잡았습니다.</p><h2>영어 이름을 보내고 모르면 사진을 씁니다</h2><p>주문은 복잡한 양식 없이 필요한 식재료의 영어 이름을 메시지로 보내는 방식입니다. 영어 이름을 모르거나 서로 이해하지 못하면 휴대전화에 저장한 사진을 보냅니다. 수량은 품목에 따라 개수로도, 무게로도 요청할 수 있습니다. 예를 들어 무 한 개, 망고 몇 개처럼 보내거나 고정된 양이 필요한 품목은 무게를 적습니다. 최종 가격은 함께 오는 영수증에 표시되어 있어 받은 품목과 금액을 대조하기 편했습니다.</p><div class="livingtmw-checklist"><h3>처음 주문할 때 보낼 내용</h3><ul><li>필요한 품목의 영어 이름 또는 선명한 사진</li><li>개수나 원하는 무게</li><li>대체 상품을 받아도 되는지 여부</li><li>배달받을 주소와 연락 가능한 전화번호</li><li>오전 수령이 꼭 필요한지 여부</li></ul></div><h2>아침 일찍 주문하면 당일에 받았습니다</h2><p>우리 경험으로는 아침 일찍 주문하면 재고가 있을 때 그날 오전, 준비가 더 필요하면 오후에 도착했습니다. 주문은 매일 가능했고 우리 집은 보통 3만 짯 이상을 주문했습니다. 이것은 업체가 고지한 공식 최소 금액이 아니라 실제로 우리 가족이 주문한 규모입니다. 배달비는 별도로 청구되지 않았고 결제는 주로 KBZPay를 사용했습니다.</p><h2>마트 무와 시장 무의 차이가 특히 컸습니다</h2><p>가장 기억에 남는 비교는 무였습니다. 마트에서 본 무는 손가락 정도 크기였지만 시장에서 받은 무는 종아리만큼 커서 실제 조리에 쓸 수 있는 양이 크게 달랐습니다. 대파와 양파도 자주 주문하고 과일은 용과, 망고와 그때 나오는 제철과일을 고릅니다. 가격은 마트와 비슷할 때도 있고 시장이 조금 저렴하게 느껴질 때도 있었으므로 품목별로 비교합니다. 단순 단가보다 크기, 손질 후 먹을 수 있는 양과 신선도를 함께 봐야 정확합니다.</p><h2>우기에는 수령 즉시 상태를 확인합니다</h2><p>우기에는 간혹 상태가 좋지 않은 채소가 올 수 있었습니다. 다행히 마쏘는 문제가 있는 품목의 교환이나 환불을 처리해 주어 계속 이용할 수 있었습니다. 신뢰가 생겼더라도 도착한 상자를 그대로 냉장고에 넣지 않고 무른 부분, 곰팡이, 냄새와 수량을 바로 확인합니다. 문제가 있으면 포장을 버리기 전에 사진을 찍어 Viber로 영수증과 함께 보냅니다.</p><h2>Viber 시장 배달이 잘 맞는 사람</h2><p>차량 이동 없이 신선식품을 받고 싶은 가정, 같은 품목을 반복 주문하는 사람, 사진으로 의사소통할 수 있는 사람에게 편합니다. 반면 정확한 품종이나 크기를 직접 골라야 하는 요리라면 첫 주문은 소량으로 시험하는 편이 안전합니다. 담당자 연락처는 가족이 개인적으로 이용하는 번호라 이 글에 공개하지 않습니다. 지인 소개로 연결되었다면 주문 가능 지역과 최신 조건을 직접 물어보는 것이 좋습니다.</p><h2>자주 묻는 질문</h2><h3>미얀마어를 못해도 주문할 수 있나요?</h3><p>우리 가족은 영어 품목명과 사진으로 주문했습니다. 주소나 수량이 모호하지 않게 숫자를 함께 보내는 것이 도움이 됐습니다.</p><h3>시장 배달이 항상 마트보다 싼가요?</h3><p>그렇지는 않았습니다. 비슷한 때도 있었지만 크기와 신선도를 포함하면 시장 쪽 만족도가 높았습니다.</p>' . livingtmw_experience_post_footer( $checked ),
		),
		array(
			'date'    => '2026-08-24 09:00:00',
			'slug'    => 'yangon-coway-wave-water-cost-comparison',
			'title'   => '양곤 Coway 정수기와 Wave 생수 비용 비교: 2인 가정 실제 사용기',
			'excerpt' => '7년 렌탈 정수기와 330mL 생수를 직접 사용하며 계산한 초기비용, 월비용, 관리 방문과 운반 부담을 비교했습니다.',
			'content' => '<p class="livingtmw-field-badge">2026년 4~8월 · 양곤 2인 가정의 직접 사용 기록</p><p>양곤에서 마실 물을 정할 때 우리 가족도 생수를 계속 살지, 정수기를 설치할지 고민했습니다. 집에는 Coway 정수기를 설치했고 다른 생활공간에서는 Wave 330mL 생수를 직접 사서 사용해 두 방식의 비용과 번거로움을 모두 경험했습니다. 결론은 어느 물이 무조건 낫다는 것이 아니라 계약기간, 사용량, 운반 가능 여부와 수질 확인 방법을 함께 봐야 한다는 것입니다.</p>' . $purifier_photo . '<h2>우리 집의 7년 렌탈 조건</h2><p>2026년 4월 설치 당시 선택한 Coway 계약은 7년이었습니다. 첫 달에 낸 초기 비용은 보증금과 설치비 명목을 합쳐 70만 짯이었고 이후에는 매달 8만 짯을 냅니다. 초기 납부액은 계약 종료 때 돌려받는 보증금이 아니라고 안내받았습니다. 월 비용은 KBZPay로 결제할 수 있습니다.</p><p>5년 계약은 월 10만 짯, 초기 비용 약 100만 짯으로 기억하지만 실제 계약서를 다시 확인하지 못했으므로 이 글의 확정 가격표에는 넣지 않습니다. 장기 계약은 월 납부액만 보고 결정하면 안 됩니다. 중도해지, 이사할 때 이전 설치, 고장 수리, 계약 종료 후 소유권과 총 납부액을 서면으로 확인해야 합니다.</p><h2>매달 방문하지만 필터를 매번 바꾸는 것은 아닙니다</h2><p>직원이 한 달에 한 번 방문해 정수기를 점검하고 청소합니다. 필터는 매달 무조건 새것으로 바꾸는 방식이 아니라 정해진 교체 주기에 맞춰 교체합니다. 방문 비용은 계약에 포함된 관리 조건을 기준으로 하되, 우리 집에서는 현금 또는 KBZPay로 안내된 비용을 처리할 수 있었습니다. 방문 날짜, 교체한 필터와 다음 교체 예정일을 사진이나 메시지로 남겨 두면 관리 상태를 확인하기 쉽습니다.</p><h2>Wave 생수를 2명이 마셨을 때의 계산</h2><p>Wave 생수는 330mL 12병 한 묶음이 5,500짯이었습니다. 2인 가정에서 한 달 약 20묶음, 총 240병을 사용해 약 11만 짯이 들었습니다. 별도 배달을 이용하지 않고 직접 사서 옮겼기 때문에 비용보다 운반과 플라스틱 폐기가 더 번거롭게 느껴졌습니다. 작은 병은 외출이나 손님용으로 편하지만 집에서 계속 마시면 병 수가 빠르게 늘어납니다.</p><div class="livingtmw-table-wrap"><table><thead><tr><th>항목</th><th>Coway 정수기</th><th>Wave 330mL 생수</th></tr></thead><tbody><tr><td>우리 집 월비용</td><td>8만 짯</td><td>약 11만 짯</td></tr><tr><td>초기비용</td><td>70만 짯</td><td>없음</td></tr><tr><td>관리</td><td>월 1회 점검·청소</td><td>직접 구입·운반·폐기</td></tr><tr><td>계약</td><td>7년 장기계약</td><td>필요할 때 구입</td></tr></tbody></table></div><p>Alpine 브랜드는 같은 판매가에 주문 배달이 가능하고 배달비가 약 1만 짯이라고 들었지만 직접 주문해 보지는 않았습니다. 따라서 이 내용은 선택지 탐색용으로만 보고 최신 최소 주문량과 배달 지역을 판매처에 확인해야 합니다.</p><h2>수질은 직원 설명만 믿고 단정하지 않았습니다</h2><p>Coway 직원에게는 정수기 물이 생수보다 수질이 좋다는 설명을 들었습니다. 그러나 이는 우리 집 물을 독립 검사한 결과가 아닙니다. 건물의 원수, 배관과 물탱크 상태, 필터 종류와 교체 주기에 따라 결과가 달라질 수 있습니다. 냄새나 색이 달라지거나 정수기 관리가 지연되면 마시지 말고 관리실과 업체에 확인하고, 건강상 우려가 있으면 공인된 수질검사와 의료진의 조언을 받는 편이 안전합니다.</p><h2>자주 묻는 질문</h2><h3>월 8만 짯이면 정수기가 무조건 더 싼가요?</h3><p>월 사용료만 보면 우리 사례에서는 생수보다 낮았지만 70만 짯의 초기비용과 7년 계약이 있습니다. 거주기간이 짧다면 총비용이 달라집니다.</p><h3>생수는 왜 계속 사용했나요?</h3><p>작은 병은 장소를 옮기거나 여러 사람이 나눠 마실 때 편했습니다. 다만 2인 기준 월 240병의 운반과 폐기 부담이 컸습니다.</p>' . livingtmw_experience_post_footer( $checked, array( 'Coway 공식 방문관리 서비스 소개' => 'https://www.coway.com/cowayservice/service_story' ) ),
		),
		array(
			'date'    => '2026-08-25 09:00:00',
			'slug'    => 'yangon-korean-family-medicine-kit-cll',
			'title'   => '양곤에서 한국 상비약 준비하기: CLL 진료와 유아 감기약 경험',
			'excerpt' => 'CLL 진료 후 병원에서 바로 약을 받은 과정과 한국에서 준비하는 상비약, 유아약이 부족했을 때의 경험을 안전수칙과 함께 정리했습니다.',
			'content' => '<p class="livingtmw-field-badge">2026년 8월 · 양곤 거주 가족의 진료·상비약 경험</p><p>양곤에서 아프면 우리 가족은 CLL을 자주 이용합니다. 진료가 끝나면 처방 내용이 병원 약 구매 과정으로 이어져 이동하지 않고 약을 받을 수 있었습니다. 외국인이라 현지 보험이 없었지만 실제 경험한 의사 진료비는 약 10만~15만 짯, 약값은 보통 약 5만 짯이었습니다. 질환, 검사와 약 종류에 따라 달라지는 개인 사례이지 표준 진료비는 아닙니다.</p><h2>진료 전에 영어로 정리하면 설명이 쉬웠습니다</h2><p>병원에서는 약 정보가 영문으로 제공됐고 의료진과 영어로 복용법을 확인할 수 있었습니다. 방문 전 증상 시작일, 체온, 알레르기, 평소 먹는 약과 한국에서 복용한 약의 영문 성분명을 메모해 두면 좋습니다. 진료 후에는 약 이름, 한 번에 먹는 양, 하루 횟수, 복용기간과 음식 전후 여부를 다시 읽어 확인합니다.</p><div class="livingtmw-checklist"><h3>우리 집이 한국에서 준비하는 상비약</h3><ul><li>연령과 체중에 맞는 해열제와 유아용 약</li><li>소화제와 의사가 권한 장염 관련 약</li><li>감기 증상에 쓰는 일반약</li><li>상처나 피부 증상에 쓰는 연고</li><li>제품 설명서와 성분·유효기간 기록</li></ul></div><p>미얀마에서 음식 때문에 배탈이나 식중독이 걱정돼 장염 관련 약도 준비합니다. 하지만 설사와 구토가 있다고 남은 항생제나 다른 사람의 처방약을 임의로 먹는 것은 피해야 합니다. 특히 아이는 탈수가 빠르고 약의 용량이 체중에 따라 달라질 수 있어 심한 증상, 고열, 의식 저하, 혈변 또는 물을 마시지 못하는 상태라면 상비약으로 버티지 말고 의료기관의 안내를 받아야 합니다.</p><h2>유아용 감기약이 없었던 날 배운 점</h2><p>한 번은 유아용 감기약을 준비하지 못한 상태에서 아이에게 목감기와 코감기 증상이 나타났습니다. 교민 단체 카카오톡방에 상황을 올렸고 한 주재원이 가지고 있던 챔프 유아용 제품을 나눠 주었습니다. 당시에는 큰 도움이 됐지만 이 경험을 같은 제품의 복용 권장으로 받아들이면 안 됩니다. 아이의 나이, 체중, 성분 중복과 증상에 따라 적절한 약이 다르므로 의료진이나 약사에게 먼저 확인해야 합니다.</p><p>그 뒤로는 유아약의 잔량과 유효기간을 출국 전 확인하고, 제품명보다 성분명과 농도를 함께 기록합니다. 여러 감기약과 해열제를 동시에 먹일 때 같은 성분이 겹칠 수 있으므로 계량도구와 투약 시간을 메모합니다.</p><h2>한국 제품을 현지에서 살 때 확인한 것</h2><p>쿠스와 채움 같은 한식당에서 타이레놀, 판피린과 복통 관련 일반약을 본 적이 있습니다. 한국 제품은 미얀마에서 대체로 한국 가격의 3~4배로 느껴졌습니다. 다만 식당이 의약품의 공식 판매처인지, 모든 제품의 유통과 보관 조건이 같은지는 확인하지 못했습니다. 구입 전 밀봉 상태, 유효기간, 성분과 보관 온도를 보고 의심스러우면 병원이나 정식 약국을 이용하는 것이 안전합니다.</p><h2>교민 도움은 응급의료를 대신하지 않습니다</h2><p>교민 단톡방은 급하게 필요한 물건이나 한국어 정보를 찾는 데 도움이 됐습니다. 그러나 다른 사람의 처방약을 나누거나 복용법을 추측하는 공간으로 쓰면 위험합니다. 도움을 받더라도 제품 사진과 성분을 의료진에게 보여 주고, 응급 증상은 즉시 병원으로 가는 기준을 가족끼리 정해 두는 편이 좋습니다.</p><h2>자주 묻는 질문</h2><h3>CLL에서 약까지 바로 살 수 있었나요?</h3><p>우리 경험에서는 진료 후 처방이 병원 약 구매로 연결됐습니다. 방문 지점과 진료과에 따라 절차가 달라질 수 있습니다.</p><h3>WHO 지원 때문에 약값이 싼가요?</h3><p>그 인과관계는 확인하지 못했습니다. 이 글에서는 보험 없이 실제 지불한 금액만 경험값으로 제시합니다.</p>' . livingtmw_experience_post_footer( $checked, array( 'CLL HEALTH 공식 시설·예약 안내' => 'https://www.cllhealth.com/locations/', 'WHO 미얀마 항생제 내성 예방 안내' => 'https://cdn.who.int/media/docs/default-source/searo/myanmar/documents/antimicrobial-resistance.pdf' ) ),
		),
